cpLogisticBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "cpLogisticBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "clinpred",
                name = "cpLogistic",
                version = c(0,3,0),
                options = options,
                results = cpLogisticResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'none')
        }))

#' Binary Outcome (Logistic)
#'
#' Develop and validate a logistic prediction model for a binary outcome: 
#' discrimination, calibration, overall performance and clinical utility, 
#' internal validation by bootstrap or cross-validation, validation in a 
#' subset of the data or in an external data file, variable importance 
#' (Shapley R² decomposition, permutation importance, SHAP) and the stability 
#' of individual predictions.
#'
#' @examples
#' data <- MASS::Pima.tr
#' cpLogistic(data, dep = "type", covs = c("npreg", "bmi", "ped"),
#'            splineVars = "glu", validation = "boot", nBoot = 100)
#'
#' @param data the data as a data frame
#' @param dep a string naming the binary outcome variable
#' @param eventLevel the level of the outcome that is the event; '' (default)
#'   uses the second level
#' @param covs numeric predictors entered as linear terms
#' @param splineVars numeric predictors entered as restricted cubic splines,
#'   allowing a non-linear association
#' @param factors categorical predictors; the first level is the reference
#' @param refLevels a list of lists \code{list(var = , ref = )} with the
#'   reference level of each factor (default: the first level)
#' @param covScales a list of lists \code{list(var = , scale = )}: the unit of
#'   the odds ratio of each linear covariate, \code{'unit'} (default),
#'   \code{'sd'}, \code{'ten'}, \code{'hundred'} or \code{'thousand'}; the
#'   covariate is divided by it before fitting, so predictions do not change
#' @param baseline a list of lists \code{list(var = , forced = TRUE)}: the
#'   predictors that are always in the model (never removed by selection, never
#'   penalised); they form the baseline model of the incremental-value
#'   comparison
#' @param selMode \code{'none'}, \code{'backward'}, \code{'forward'} or
#'   \code{'enet'}: selection of the predictors that are not baseline
#'   covariates, repeated in every bootstrap or cross-validation fit
#' @param selCrit .
#' @param selAlpha .
#' @param enetAlpha the elastic net mixing parameter alpha (1 lasso, 0 ridge)
#' @param enetRule .
#' @param enetFolds .
#' @param enetTune in bootstrap and cross-validation fits, choose λ again by
#'   cross-validation (honest, slower) instead of using the λ of the final model
#' @param incremental compare the baseline model (baseline covariates only)
#'   with the full model: differences in performance (apparent,
#'   optimism-corrected and in validation data), LR test of the added
#'   predictors, reclassification and net benefit
#' @param interactions a list of pairs of predictors, the candidate
#'   interaction terms
#' @param intAllPairs .
#' @param intMode \code{'all'} keeps every candidate interaction;
#'   \code{'aic'}, \code{'bic'} or \code{'lrt'} select them forward (repeated
#'   within each bootstrap or cross-validation fit)
#' @param intAlpha .
#' @param knots number of knots of the restricted cubic splines (3 to 7)
#' @param splitVar a variable that marks the rows used for validation only
#'   (e.g. a later period or another centre)
#' @param splitLevel the level of splitVar that marks validation rows; ''
#'   (default) uses the second level
#' @param extFile a file with the external validation data (csv, tsv, txt,
#'   omv, xlsx or sav), with the same variable names as the development data
#' @param updating in the validation data, compare the original model with
#'   recalibration in the large, recalibration and model revision, and choose
#'   among them by the closed testing procedure
#' @param updAlpha .
#' @param validation \code{'none'}, \code{'boot'} (Harrell's bootstrap
#'   optimism correction) or \code{'cv'} (repeated k-fold cross-validation)
#' @param nBoot .
#' @param nFolds .
#' @param nRepeats .
#' @param seed .
#' @param ciWidth .
#' @param descTable .
#' @param descStat .
#' @param oddsRatios .
#' @param crude .
#' @param predTests .
#' @param coefs .
#' @param equation .
#' @param sampleSize .
#' @param ssSource .
#' @param ssR2 .
#' @param classif .
#' @param thrMethod .
#' @param threshold .
#' @param dca .
#' @param dcaMax .
#' @param nbThresholds .
#' @param shapley .
#' @param shapleyMeasure .
#' @param permImp .
#' @param nPerm .
#' @param shap .
#' @param shapRow .
#' @param rocPlot .
#' @param calPlot .
#' @param calGroups .
#' @param riskPlot .
#' @param stability .
#' @param explain .
#' @param exportModel writes the fitted model (predictors, coding, spline
#'   knots, coefficients and, for Cox, the baseline survival at the horizon) to
#'   a JSON file, which Validate a Published Model reads
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$instructions} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$samples} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$extCheck} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$caseMix} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$descTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$orTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$testTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$intTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$selTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$incTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$subTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$coefTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$equationText} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$perfDev} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$perfVal} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$updTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$stabTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$confTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$classTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$nbTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ssTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$shapleyTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$permTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$shapTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plots$roc} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$calibration} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$riskDist} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$dcaCurves} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$shapleyBar} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$permBar} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$shapSummary} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$shapPatient} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$enetCv} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$incDca} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$instability} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plots$calInstability} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$predRisk} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$predLP} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$samples$asDF}
#'
#' \code{as.data.frame(results$samples)}
#'
#' @export
cpLogistic <- function(
    data,
    dep,
    eventLevel = "",
    covs = list(),
    splineVars = list(),
    factors = list(),
    refLevels = NULL,
    covScales = NULL,
    baseline = NULL,
    selMode = "none",
    selCrit = "aic",
    selAlpha = 0.05,
    enetAlpha = 0.5,
    enetRule = "min",
    enetFolds = 10,
    enetTune = TRUE,
    incremental = FALSE,
    interactions = NULL,
    intAllPairs = FALSE,
    intMode = "all",
    intAlpha = 0.05,
    knots = 4,
    splitVar = NULL,
    splitLevel = "",
    extFile = NULL,
    updating = FALSE,
    updAlpha = 0.05,
    validation = "none",
    nBoot = 200,
    nFolds = 10,
    nRepeats = 5,
    seed = 1234,
    ciWidth = 95,
    descTable = FALSE,
    descStat = "meanSD",
    oddsRatios = TRUE,
    crude = TRUE,
    predTests = FALSE,
    coefs = FALSE,
    equation = FALSE,
    sampleSize = FALSE,
    ssSource = "model",
    ssR2 = 0.1,
    classif = FALSE,
    thrMethod = "value",
    threshold = 0.5,
    dca = FALSE,
    dcaMax = 0.5,
    nbThresholds = "0.05, 0.1, 0.2",
    shapley = FALSE,
    shapleyMeasure = "r2mf",
    permImp = FALSE,
    nPerm = 20,
    shap = FALSE,
    shapRow = 0,
    rocPlot = FALSE,
    calPlot = FALSE,
    calGroups = 10,
    riskPlot = FALSE,
    stability = FALSE,
    explain = FALSE,
    exportModel = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("cpLogistic requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(splineVars)) splineVars <- jmvcore::resolveQuo(jmvcore::enquo(splineVars))
    if ( ! missing(factors)) factors <- jmvcore::resolveQuo(jmvcore::enquo(factors))
    if ( ! missing(splitVar)) splitVar <- jmvcore::resolveQuo(jmvcore::enquo(splitVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(splineVars), splineVars, NULL),
            `if`( ! missing(factors), factors, NULL),
            `if`( ! missing(splitVar), splitVar, NULL))

    for (v in dep) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in factors) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in splitVar) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    if (inherits(interactions, "formula")) interactions <- jmvcore::decomposeFormula(interactions)

    options <- cpLogisticOptions$new(
        dep = dep,
        eventLevel = eventLevel,
        covs = covs,
        splineVars = splineVars,
        factors = factors,
        refLevels = refLevels,
        covScales = covScales,
        baseline = baseline,
        selMode = selMode,
        selCrit = selCrit,
        selAlpha = selAlpha,
        enetAlpha = enetAlpha,
        enetRule = enetRule,
        enetFolds = enetFolds,
        enetTune = enetTune,
        incremental = incremental,
        interactions = interactions,
        intAllPairs = intAllPairs,
        intMode = intMode,
        intAlpha = intAlpha,
        knots = knots,
        splitVar = splitVar,
        splitLevel = splitLevel,
        extFile = extFile,
        updating = updating,
        updAlpha = updAlpha,
        validation = validation,
        nBoot = nBoot,
        nFolds = nFolds,
        nRepeats = nRepeats,
        seed = seed,
        ciWidth = ciWidth,
        descTable = descTable,
        descStat = descStat,
        oddsRatios = oddsRatios,
        crude = crude,
        predTests = predTests,
        coefs = coefs,
        equation = equation,
        sampleSize = sampleSize,
        ssSource = ssSource,
        ssR2 = ssR2,
        classif = classif,
        thrMethod = thrMethod,
        threshold = threshold,
        dca = dca,
        dcaMax = dcaMax,
        nbThresholds = nbThresholds,
        shapley = shapley,
        shapleyMeasure = shapleyMeasure,
        permImp = permImp,
        nPerm = nPerm,
        shap = shap,
        shapRow = shapRow,
        rocPlot = rocPlot,
        calPlot = calPlot,
        calGroups = calGroups,
        riskPlot = riskPlot,
        stability = stability,
        explain = explain,
        exportModel = exportModel)

    analysis <- cpLogisticClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

